ext('c12_bus_ch1',[
C("🏢","संगठन का उद्देश्य और प्रबंध",["संगठन किसी लक्ष्य के लिए बनता है","लक्ष्य अकेले पूरा नहीं होता","प्रबंधक संसाधनों को जोड़ता है","लक्ष्य की ओर मार्गदर्शन"],"कोई भी संगठन किसी उद्देश्य के लिए बनाया जाता है, जैसे सामान बनाना या सेवा देना। यह उद्देश्य एक अकेला व्यक्ति पूरा नहीं कर सकता। इसलिए अलग-अलग लोग, पैसा और मशीन साथ मिलाकर काम करते हैं। इन सबको सही दिशा में जोड़ने का काम प्रबंधक करता है, और यही प्रबंध है।"),
C("👥","प्रबंध की सार्वभौमिकता",["हर प्रकार के संगठन में ज़रूरी","स्कूल, अस्पताल, दुकान, फ़ैक्टरी","सिद्धांत सब जगह लागू","तरीके स्थिति के अनुसार बदलें"],"प्रबंध केवल कंपनियों में नहीं, हर संगठन में ज़रूरी होता है। स्कूल, अस्पताल, दुकान और फ़ैक्टरी सभी में प्रबंध करना पड़ता है। इसके मूल सिद्धांत सब जगह लागू होते हैं। लेकिन उन्हें लागू करने का तरीका स्थिति के अनुसार बदलना पड़ता है।"),
C("🎯","प्रबंध के तीन प्रकार के उद्देश्य",["संगठनात्मक: टिके रहना, लाभ, वृद्धि","सामाजिक: समाज के प्रति दायित्व","व्यक्तिगत: कर्मचारियों की ज़रूरतें","तीनों का संतुलन ज़रूरी"],"प्रबंध के तीन तरह के उद्देश्य होते हैं। संगठनात्मक उद्देश्य हैं, संगठन का टिके रहना, लाभ कमाना और बढ़ना। सामाजिक उद्देश्य हैं, समाज के प्रति अपना दायित्व निभाना। व्यक्तिगत उद्देश्य हैं, कर्मचारियों की ज़रूरतें और विकास। अच्छा प्रबंधक इन तीनों में संतुलन रखता है।"),
C("🧠","प्रबंध और प्रशासन",["प्रशासन: बड़े नीतिगत निर्णय","प्रबंध: निर्णयों को लागू करना","प्रशासन ऊपरी स्तर पर","प्रबंध मध्य और निचले स्तर पर"],"कुछ विद्वान प्रशासन और प्रबंध को अलग मानते हैं। प्रशासन में बड़े नीतिगत निर्णय लिए जाते हैं। प्रबंध में उन निर्णयों को लागू कराया जाता है। प्रशासन ऊपरी स्तर का काम है, और प्रबंध मध्य और निचले स्तर का। आज दोनों शब्द लगभग एक ही अर्थ में इस्तेमाल होते हैं।"),
C("📈","प्रबंध की प्रक्रिया में समन्वय",["अलग-अलग विभाग आपस में जुड़ें","एक जैसी दिशा में काम","टकराव और दोहराव से बचाव","समन्वय सभी कार्यों में दिखता है"],"संगठन में कई विभाग होते हैं, जैसे उत्पादन, बिक्री और वित्त। समन्वय का काम है इन सबको एक ही दिशा में चलाना। इससे काम में टकराव और दोहराव कम होता है। समन्वय अलग से किया जाने वाला काम नहीं है, वह नियोजन, संगठन, नियुक्ति, निर्देशन और नियंत्रण, सभी में दिखता है।"),
C("🌟","प्रबंध एक पेशे के रूप में",["विशेष ज्ञान और प्रशिक्षण","पेशेवर संघ और आचार संहिता","सेवा का भाव","प्रबंध में अभी पूर्ण पेशा नहीं"],"पेशे में विशेष ज्ञान, प्रशिक्षण, पेशेवर संघ, आचार संहिता और सेवा का भाव होता है। चिकित्सा और वकालत इसके उदाहरण हैं। प्रबंध में इनमें से कई बातें हैं, जैसे ज्ञान और प्रशिक्षण। लेकिन प्रबंधक बनने के लिए कोई अनिवार्य डिग्री नहीं है, इसलिए इसे पूर्ण पेशा नहीं माना जाता।"),
],5)
ext('c12_bus_ch8',[
C("📏","मानक कैसे तय होते हैं",["मात्रा में मानक","गुणवत्ता में मानक","लागत और समय में मानक","मापने योग्य और व्यावहारिक"],"नियंत्रण का पहला कदम मानक तय करना है। मानक मात्रा, गुणवत्ता, लागत या समय के रूप में हो सकते हैं। जैसे, एक दिन में सौ वस्तुएँ बनाना। मानक ऐसे होने चाहिए जिन्हें मापा जा सके और जो व्यावहारिक हों, तभी वास्तविक प्रदर्शन से उनकी तुलना हो सकती है।"),
C("🔍","विचलन का विश्लेषण",["वास्तविक और मानक में अंतर","कितना विचलन स्वीकार्य","महत्त्वपूर्ण क्षेत्रों पर ध्यान","अपवाद का सिद्धांत"],"जब वास्तविक प्रदर्शन मानक से अलग होता है, तो उसे विचलन कहते हैं। हर छोटे विचलन पर चिंता करना ज़रूरी नहीं होता। केवल उन विचलनों पर ध्यान देना चाहिए जो सीमा से बाहर हों या महत्त्वपूर्ण क्षेत्र में हों। इसी विचार को अपवाद का सिद्धांत कहते हैं।"),
C("🛠️","सुधारात्मक कार्रवाई",["कारण की खोज","तुरंत सुधार","ज़रूरत हो तो मानक बदलना","भविष्य में दोहराव रोकना"],"विचलन मिलने पर कारण खोजा जाता है। फिर सुधारात्मक कार्रवाई की जाती है, जैसे प्रशिक्षण देना या मशीन ठीक करना। कभी-कभी मानक ही अव्यावहारिक होता है, तब उसे बदलना पड़ता है। लक्ष्य यह है कि वही गलती दोबारा न हो।"),
C("💰","बजटीय नियंत्रण",["भविष्य की आय-व्यय की योजना","विभागवार लक्ष्य","वास्तविक खर्च से तुलना","खर्च पर नियंत्रण में सहायक"],"बजट आने वाले समय की आय और खर्च की संख्यात्मक योजना है। हर विभाग को उसका बजट दिया जाता है। बाद में असल खर्च की बजट से तुलना की जाती है। इससे पता चलता है कि कहाँ ज़्यादा खर्च हुआ, और सभी विभाग अपने लक्ष्य की दिशा में रहते हैं।"),
C("📊","अनुपात विश्लेषण",["वित्तीय आँकड़ों का अनुपात","तरलता और शोधन क्षमता","लाभप्रदता और टर्नओवर","संगठन की सेहत की जाँच"],"अनुपात विश्लेषण में वित्तीय विवरण के आँकड़ों की आपस में तुलना की जाती है। इससे तरलता, शोधन क्षमता, लाभप्रदता और गतिविधि का पता चलता है। यह संगठन की आर्थिक सेहत जाँचने का एक अच्छा तरीका है, और इससे समय पर सुधार हो सकता है।"),
C("🧑‍🤝‍🧑","नियंत्रण का मानवीय पक्ष",["कर्मचारी नियंत्रण को बाधा समझते","पारदर्शिता से विश्वास","सहभागिता से स्वीकार्यता","अत्यधिक नियंत्रण से हानि"],"कई कर्मचारी नियंत्रण को अपनी स्वतंत्रता पर रोक मानते हैं। इसलिए नियंत्रण पारदर्शी होना चाहिए और कर्मचारियों की भागीदारी ली जानी चाहिए। बहुत ज़्यादा नियंत्रण से उत्साह घटता है। संतुलित नियंत्रण से ही संगठन के लक्ष्य पूरे होते हैं।"),
],5)
ext('c12_bus_ch9',[
C("🏦","वित्तीय योजना",["कितने धन की ज़रूरत","धन कहाँ से आएगा","धन का उपयोग कहाँ","अतिरिक्त और कमी से बचाव"],"वित्तीय योजना का अर्थ है यह तय करना कि संगठन को कितना धन चाहिए, वह कहाँ से आएगा और कहाँ लगेगा। ज़रूरत से कम धन हो तो काम रुकता है। ज़रूरत से ज़्यादा धन बेकार पड़ा रहता है। इसलिए सही योजना बनाना बहुत ज़रूरी है।"),
C("🧮","स्थिर और कार्यशील पूँजी",["स्थिर पूँजी: ज़मीन, मशीन","कार्यशील पूँजी: रोज़ का खर्च","स्थिर पूँजी लंबे समय के लिए","कार्यशील पूँजी की कमी से रुकावट"],"स्थिर पूँजी में ज़मीन, इमारत और मशीन जैसी लंबे समय की संपत्तियाँ आती हैं। कार्यशील पूँजी रोज़ के खर्च के लिए होती है, जैसे कच्चा माल और वेतन। अगर कार्यशील पूँजी कम पड़ जाए तो कारोबार रुक जाता है, चाहे उसके पास बहुत संपत्ति हो।"),
C("📉","पूँजी की लागत",["पूँजी पर चुकाया जाने वाला मूल्य","ऋण पर ब्याज","शेयर पर लाभांश","सस्ती पूँजी, कम जोखिम का संतुलन"],"किसी भी स्रोत से धन लेने पर उसकी कुछ लागत चुकानी पड़ती है। ऋण पर ब्याज देना पड़ता है। शेयर पूँजी पर लाभांश देना पड़ता है। इसलिए प्रबंधक ऐसा स्रोत चुनता है जो सस्ता हो, पर जिसका जोखिम भी कम हो। यह संतुलन वित्त निर्णय में बहुत मायने रखता है।"),
C("🏭","स्थिर पूँजी को प्रभावित करने वाले तत्व",["व्यवसाय की प्रकृति","व्यापार का पैमाना","तकनीक का चुनाव","वृद्धि की संभावनाएँ"],"किसी संगठन को कितनी स्थिर पूँजी चाहिए, यह कई बातों पर निर्भर करता है। निर्माण करने वाले उद्योग को ज़्यादा स्थिर पूँजी चाहिए, जबकि व्यापार करने वाली दुकान को कम। बड़े पैमाने के कारोबार और आधुनिक तकनीक में भी ज़्यादा पूँजी लगती है। भविष्य में विस्तार हो तो भी अतिरिक्त पूँजी चाहिए।"),
C("💵","लाभांश निर्णय",["लाभ बाँटना या रोकना","बाँटने से शेयरधारक संतुष्ट","रोकने से विस्तार में मदद","स्थिर लाभांश नीति"],"कंपनी कमाया हुआ लाभ शेयरधारकों में बाँट भी सकती है और भविष्य के विस्तार के लिए रोक भी सकती है। लाभ बाँटने से शेयरधारक खुश रहते हैं। लाभ रोकने से कंपनी के पास निवेश का पैसा रहता है। इसलिए कंपनी दोनों के बीच संतुलन रखते हुए लाभांश नीति तय करती है।"),
C("🧾","वित्तीय योजना की ज़रूरत का एक उदाहरण",["नई फ़ैक्टरी का विचार","लागत का अनुमान","पूँजी के स्रोत की तुलना","समय पर लौटाने की क्षमता"],"मान लीजिए एक कंपनी नई फ़ैक्टरी बनाना चाहती है। उसे पहले कुल लागत का अनुमान लगाना होगा। फिर देखना होगा कि पैसा शेयर से लें या ऋण से। साथ ही यह भी देखना होगा कि भविष्य की कमाई से ऋण समय पर लौटाया जा सकेगा या नहीं। यही वित्तीय प्रबंध का असली काम है।"),
],5)
ext('c12_bus_ch10',[
C("📜","मुद्रा बाज़ार के कुछ साधन",["ट्रेज़री बिल: सरकार की अल्पकालीन प्रतिभूति","वाणिज्यिक पत्र","जमा प्रमाणपत्र","माँग मुद्रा"],"मुद्रा बाज़ार में एक साल तक के लिए उधार लिया-दिया जाता है। ट्रेज़री बिल सरकार की छोटी अवधि की प्रतिभूति है। वाणिज्यिक पत्र कंपनियाँ जारी करती हैं। जमा प्रमाणपत्र बैंक देते हैं। माँग मुद्रा में बैंक एक-दूसरे को एक दिन के लिए उधार देते हैं।"),
C("🏦","पूँजी बाज़ार के दो भाग",["प्राथमिक बाज़ार: नई प्रतिभूतियाँ","द्वितीयक बाज़ार: पुरानी की खरीद-बिक्री","निवेशक कंपनी को सीधा धन","बाद में आपस में व्यापार"],"पूँजी बाज़ार दो भागों में बँटा है। प्राथमिक बाज़ार में कंपनी नई प्रतिभूतियाँ जारी करके निवेशकों से सीधे धन जुटाती है। द्वितीयक बाज़ार में पहले से जारी प्रतिभूतियाँ निवेशकों के बीच खरीदी-बेची जाती हैं। इस बिक्री का पैसा कंपनी को नहीं, बेचने वाले निवेशक को मिलता है।"),
C("🧾","निर्गम के तरीके",["प्रविवरण द्वारा सार्वजनिक निर्गम","निजी नियोजन","अधिकार निर्गम","बोनस शेयर"],"प्राथमिक बाज़ार में कंपनी कई तरीकों से शेयर बेचती है। प्रविवरण के माध्यम से जनता को शेयर बेचे जा सकते हैं। निजी नियोजन में चुने हुए संस्थानों को सीधे बेचा जाता है। अधिकार निर्गम में पुराने शेयरधारकों को पहले मौका मिलता है। बोनस शेयर पुराने शेयरधारकों को मुफ़्त में दिए जाते हैं।"),
C("🛡️","निवेशकों की सुरक्षा",["सेबी का नियमन","पारदर्शी जानकारी","अनुचित व्यवहार पर रोक","निवेशकों में जागरूकता"],"शेयर बाज़ार में छोटे निवेशकों को धोखाधड़ी से बचाने के लिए सेबी काम करती है। वह कंपनियों से सही जानकारी देने को कहती है। वह अंदरूनी जानकारी से व्यापार जैसे अनुचित व्यवहार को रोकती है। साथ ही निवेशकों को जागरूक भी करती है, ताकि वे समझदारी से निवेश कर सकें।"),
C("📉","सेंसेक्स और निफ्टी",["बीएसई का सूचकांक: सेंसेक्स","एनएसई का सूचकांक: निफ्टी","चुनिंदा बड़ी कंपनियों के शेयर","बाज़ार का सामान्य रुझान"],"सेंसेक्स बीएसई का सूचकांक है और निफ्टी एनएसई का। दोनों में कुछ चुनिंदा बड़ी कंपनियों के शेयरों की कीमतें शामिल की जाती हैं। इनके बढ़ने या घटने से पता चलता है कि शेयर बाज़ार का सामान्य रुझान कैसा है।"),
C("💡","समझदारी से निवेश",["एक ही जगह धन न लगाएँ","जोखिम और लाभ की समझ","अफ़वाहों से बचें","लंबी अवधि का नज़रिया"],"निवेश में कभी भी पूरा पैसा एक ही जगह नहीं लगाना चाहिए। हर निवेश में लाभ के साथ जोखिम भी होता है, इसलिए उसे ठीक से समझना चाहिए। अफ़वाहों पर निर्णय न लें। लंबी अवधि का नज़रिया रखने से कुल जोखिम कम हो जाता है।"),
],5)
